    for (let i = B - outer; i < B; i++) if (b.cnt[i] > 0 && span(i) > thr) { if (mn < 0) mn = i; mx = i; hlo = Math.min(hlo, b.lo[i]); hhi = Math.max(hhi, b.hi[i]); mass += b.cnt[i]; }
